package com.rumitx.app.repeaters;
import android.app.*;import android.widget.*;import android.view.*;import android.location.Location;import java.util.*;import com.rumitx.app.*;
public final class RepeaterProfiles {
 public static String block(Repeater r){if(r.input==null)return "TX/input frequency is missing or this is receive-only.";if(r.output<400||r.output>470||r.input<400||r.input>470)return "This S80 supports the existing 400–470 MHz UHF path; profile is saved for reference.";if(!r.mode.equals("FM")&&!r.mode.equals("DMR"))return r.mode+" is not supported by the existing radio codec.";if(r.mode.equals("DMR")){if(r.cc==null||r.ts==null||r.tg.isEmpty())return "Complete DMR color code, timeslot, and talkgroup before programming.";return "DMR timeslot-to-UART mapping is not verified. Profile fields are saved; automatic programming remains gated.";}try{ToneIndex.resolve(tone(r.toneIn),tone(r.toneOut),r.dcsIn,r.dcsOut);}catch(IllegalArgumentException e){return e.getMessage();}return "";}
 public static String describe(Repeater r,Location p){String text=r.title()+"\n\nListen/output: "+r.output+" MHz\nTransmit/input: "+(r.input==null?"unknown / RX only":r.input+" MHz")+"\nOffset: "+(r.input==null?"unknown":String.format(Locale.US,"%+.6f MHz",r.offset()))+"\nTX tone: "+(r.toneIn.isEmpty()?"none":r.toneIn+" Hz")+" · DCS "+(r.dcsIn.isEmpty()?"none":r.dcsIn)+"\nRX tone: "+(r.toneOut.isEmpty()?"none":r.toneOut+" Hz")+" · DCS "+(r.dcsOut.isEmpty()?"none":r.dcsOut)+"\nMode: "+r.mode+"\nDMR CC: "+r.cc+" · TS: "+r.ts+"\nTalkgroups: "+(r.tg.isEmpty()?"unknown":r.tg)+"\nDMR ID: "+(r.dmrId.isEmpty()?"unknown":r.dmrId)+"\n\n"+r.city+", "+r.county+", "+r.state+"\n"+r.status+" · "+r.restriction+"\nSource: "+r.source+"\nUpdated: "+new java.util.Date(r.updated*1000);
 if(r.located())text+="\nCoordinates: "+r.latitude+", "+r.longitude;else text+="\nNo location · list only";if(p!=null&&r.located())text+=String.format(Locale.US,"\n%.1f km · bearing %.0f°",Geo.distanceKm(p.getLatitude(),p.getLongitude(),r.latitude,r.longitude),Geo.bearing(p.getLatitude(),p.getLongitude(),r.latitude,r.longitude));String gate=block(r);if(!gate.isEmpty())text+="\n\nProgramming note: "+gate;return text;}
 public static void show(FeatureActivity a,Repeater r,RepeaterDatabase db,Runnable refresh){android.app.Dialog dialog=new android.app.Dialog(a);LinearLayout body=a.column();TextView text=a.label(describe(r,a.position),15);body.addView(text);body.addView(a.button("Edit complete profile",()->{dialog.dismiss();edit(a,r,db,refresh);}));body.addView(a.button("Set PL / DCS tone",()->{TonePicker.show(a,pickerTone(r.toneIn),r.dcsIn,(hz,code)->{r.toneIn=r.toneOut=hz==0?"":String.valueOf(hz);r.dcsIn=r.dcsOut=code;db.updateProfile(r.id,r);dialog.dismiss();refresh.run();show(a,r,db,refresh);});}));body.addView(a.button("Add to channels",()->add(a,r,db)));body.addView(a.button("Close",dialog::dismiss));ScrollView scroll=new ScrollView(a);scroll.addView(body);dialog.setContentView(scroll);android.view.Window w=dialog.getWindow();if(w!=null){w.setLayout(-1,(int)(a.getResources().getDisplayMetrics().heightPixels*.85));w.setGravity(Gravity.BOTTOM);}dialog.show();if(w!=null)w.setLayout(-1,(int)(a.getResources().getDisplayMetrics().heightPixels*.85));}
 public static void edit(FeatureActivity a,Repeater r,RepeaterDatabase db,Runnable refresh){LinearLayout body=a.column();LinkedHashMap<String,EditText> fields=new LinkedHashMap<>();String[][] entries={{"Callsign",r.callsign},{"Name",r.name},{"Frequency",""+r.output},{"Input Frequency",r.input==null?"":""+r.input},{"Offset",r.input==null?"":String.valueOf(r.offset())},{"Tone In",r.toneIn},{"Tone Out",r.toneOut},{"DCS In",r.dcsIn},{"DCS Out",r.dcsOut},{"Mode",r.mode},{"DMR Color Code",r.cc==null?"":""+r.cc},{"Timeslot",r.ts==null?"":""+r.ts},{"Talkgroups",r.tg},{"DMR ID",r.dmrId},{"Latitude",r.latitude==null?"":""+r.latitude},{"Longitude",r.longitude==null?"":""+r.longitude},{"City",r.city},{"County",r.county},{"State",r.state},{"Status",r.status},{"Use",r.restriction},{"Source",r.source}};for(String[] entry:entries){body.addView(a.label(entry[0],12));EditText e=new EditText(a);e.setSingleLine(true);e.setText(entry[1]);e.setMinHeight(48);fields.put(entry[0],e);body.addView(e);}body.addView(a.label("To calculate input from offset, clear Input Frequency. Missing coordinates keep this record in the list only.",12));ScrollView scroll=new ScrollView(a);scroll.addView(body);AlertDialog d=new AlertDialog.Builder(a).setTitle("Complete repeater profile").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(b->{try{Map<String,String> values=new HashMap<>();for(Map.Entry<String,EditText> e:fields.entrySet())values.put(e.getKey(),e.getValue().getText().toString());Repeater changed=RepeaterParser.parse(values);changed.id=r.id;db.updateProfile(r.id,changed);d.dismiss();refresh.run();}catch(Exception e){a.message("Profile not saved: "+e.getMessage());}}));d.show();}
 private static double pickerTone(String s){try{return tone(s);}catch(IllegalArgumentException e){return 0;}}
 private static double tone(String s){if(s==null||s.trim().isEmpty())return 0;try{return Double.parseDouble(s);}catch(Exception e){throw new IllegalArgumentException("Tone-to-module-index mapping is not verified for "+s);}}
 public static void add(FeatureActivity a,Repeater r,RepeaterDatabase db){String reason=block(r);try{tone(r.toneIn);tone(r.toneOut);}catch(IllegalArgumentException e){a.message("Profile retained. "+e.getMessage()+". Use the tone picker before adding to channels.");return;}Channel c=new Channel();c.id=db.linkedChannel(r.id);c.name=r.title();c.rxFreqMHz=r.output;c.txFreqMHz=r.input==null?r.output:r.input;c.txCtcssHz=tone(r.toneIn);c.rxCtcssHz=tone(r.toneOut);c.txDcsCode=r.dcsIn;c.rxDcsCode=r.dcsOut;c.isDigital=r.mode.equals("DMR");if(r.cc!=null)c.colorCode=r.cc;if(r.ts!=null)c.timeslot=r.ts;try{c.talkgroup=Integer.parseInt(r.tg);}catch(Exception ignored){}c.squelchLevel=2;
  ChannelDatabase channels=new ChannelDatabase(a);long id=channels.saveChannel(c);channels.close();if(id<0){a.message("Channel could not be saved.");return;}db.link(id,r.id,reason);if(!reason.isEmpty()){a.message("Saved to channel memory. "+reason);return;}new AlertDialog.Builder(a).setTitle("Program radio channel?").setMessage("RX "+c.rxFreqMHz+" MHz · TX "+c.txFreqMHz+" MHz\nIf only one tone is supplied, it is applied to TX and RX.\n"+describe(r,null)).setNegativeButton("Later",null).setPositiveButton("Program",(confirm,which)->new Thread(()->{boolean ok=false;String error="";try{ok=RadioController.getInstance().programChannel(c);}catch(Exception e){error=e.getMessage();}final String message=ok?"Added to channels and module programming acknowledged. RF operation still depends on the repeater and field verification.":"Added to channels; module programming failed. "+error;a.runOnUiThread(()->a.message(message));},"RumiTX-repeater-program").start()).show();
 }
 public static String blockedChannel(Channel channel){return channel instanceof Blocked?((Blocked)channel).reason:null;}
 public static Channel decorate(android.content.Context context,Channel base){String reason;RepeaterDatabase db=new RepeaterDatabase(context);try{reason=db.block(base.id);if(reason!=null){try{if(!base.isDigital){ToneIndex.resolve(base.txCtcssHz,base.rxCtcssHz,base.txDcsCode,base.rxDcsCode);if(reason.startsWith("CTCSS/DCS")||reason.startsWith("Tone-to-module-index")||reason.startsWith("Mixed CTCSS/DCS")||reason.startsWith("TX/RX DCS polarity"))reason="";}}catch(IllegalArgumentException e){reason=e.getMessage();}}}finally{db.close();}if(reason==null||reason.isEmpty())return base;return new Blocked(base,reason);}
 private static final class Blocked extends Channel {private final String reason;Blocked(Channel c,String reason){this.reason=reason;id=c.id;name=c.name;txFreqMHz=c.txFreqMHz;rxFreqMHz=c.rxFreqMHz;txCtcssHz=c.txCtcssHz;rxCtcssHz=c.rxCtcssHz;txDcsCode=c.txDcsCode;rxDcsCode=c.rxDcsCode;isDigital=c.isDigital;colorCode=c.colorCode;talkgroup=c.talkgroup;timeslot=c.timeslot;bandwidthKhz=c.bandwidthKhz;squelchLevel=c.squelchLevel;}public String buildProgramFrame(){throw new IllegalArgumentException(reason);}}
}
